Lemma fz_half_live : forall pc vc cc r vr (L1 : list (Z * Z)),
  List.NoDup (map fst (OPTX r vr ++ pm_copy_live pc vc cc L1)) -> p_data vc <> 0 -> (p_cmap vc <> 0 -> c_arr cc <> 0) ->
  (r <> 0 -> p_data vr <> 0 /\ p_cmap vr = 0) ->
  (if r =? 0 then live_destroy pc vc cc (OPTX r vr ++ pm_copy_live pc vc cc L1)
   else live_destroy r vr (mkCmapv 0 0 0 0) (live_destroy pc vc cc (OPTX r vr ++ pm_copy_live pc vc cc L1))) = L1.
